<script setup lang="ts">
import { v4 as newRequestKey } from "uuid";
import { computed,onMounted,ref,watch } from "vue";
import { useRoute } from "vue-router";
import { useResellerAuth } from "@papilio/auth";
import { ApiError,item,request,query,type Page,type BilledSubscription,type Customer,type Reseller,type ResellerPlan } from "@papilio/api";
import { faNumber,faDate,toman } from "@papilio/ui";
import { useI18n } from "vue-i18n";
const route=useRoute(),auth=useResellerAuth();
const {t}=useI18n();
const customer=ref<Customer|null>(null),profile=ref<Reseller|null>(null),rows=ref<BilledSubscription[]>([]),selected=ref<BilledSubscription|null>(null);
const page=ref(1),pages=ref(1),total=ref(0),status=ref(""),loading=ref(false),busy=ref(false),error=ref(""),notice=ref("");
const plans=ref<ResellerPlan[]>([]),planPage=ref(1),planPages=ref(1),planTotal=ref(0),q=ref(""),planLoading=ref(false),planError=ref(""),chosen=ref<ResellerPlan|null>(null);
const payer=ref<""|"reseller_wallet"|"customer_wallet">(""),autoRenew=ref(false);
interface PurchaseIntent {customer_id:number;plan_id:number;payer_mode:"reseller_wallet"|"customer_wallet";purchase_key:string;expected_price_rial:number;auto_renew:boolean}
const intent=ref<PurchaseIntent|null>(null),purchaseKey=ref(""),intentError=ref("");
const customerId=computed(()=>route.params.customerId?Number(route.params.customerId):undefined);
const storageKey=computed(()=>`papilio:purchase:${auth.session?.account_id}:${customerId.value}`);
const labels=computed<Record<string,string>>(()=>({active:t("resellerSubscriptions.states.active"),pending_provision:t("resellerSubscriptions.states.pending"),expired:t("resellerSubscriptions.states.expired"),exhausted:t("resellerSubscriptions.states.exhausted"),revoking:t("resellerSubscriptions.states.revoking"),suspended:t("resellerSubscriptions.states.suspended"),failed:t("resellerSubscriptions.states.failed"),cancelled:t("resellerSubscriptions.states.cancelled")}));
let version=0,selectionVersion=0,planVersion=0;
function remember(value:PurchaseIntent|null):void{try{if(value)sessionStorage.setItem(storageKey.value,JSON.stringify(value));else sessionStorage.removeItem(storageKey.value);}catch{throw new Error(t("resellerSubscriptions.storageFailed"));}}
function restoreIntent():void{try{const stored=sessionStorage.getItem(storageKey.value);if(!stored)return;const parsed:unknown=JSON.parse(stored);if(!parsed||typeof parsed!=="object")throw new Error();const value=parsed as Partial<PurchaseIntent>;if(value.customer_id!==customerId.value||!Number.isSafeInteger(value.plan_id)||Number(value.plan_id)<=0||typeof value.purchase_key!=="string"||value.purchase_key.length<8||value.purchase_key.length>128||!Number.isSafeInteger(value.expected_price_rial)||Number(value.expected_price_rial)<0||typeof value.auto_renew!=="boolean"||!(["reseller_wallet","customer_wallet"] as const).includes(value.payer_mode as "reseller_wallet"|"customer_wallet"))throw new Error();intent.value=value as PurchaseIntent;purchaseKey.value=value.purchase_key;payer.value=value.payer_mode!;autoRenew.value=value.auto_renew;notice.value=t("resellerSubscriptions.intentPending");}catch{intentError.value=t("resellerSubscriptions.invalidIntent");}}
async function start():Promise<void>{error.value="";if(customerId.value){try{const [record,organization]=await Promise.all([item<Customer>(`/v1/reseller/customers/${customerId.value}`),item<Reseller>("/v1/reseller/profile")]);customer.value=record;profile.value=organization;if(organization.policy.payer_mode!=="either")payer.value=organization.policy.payer_mode;restoreIntent();}catch(cause){error.value=cause instanceof Error?cause.message:t("resellerSubscriptions.operationFailed");return;}}await load();}
async function load():Promise<void>{const current=++version;loading.value=true;error.value="";try{const result=await request<Page<BilledSubscription>>(`/v1/reseller/subscriptions?${query({page:page.value,status:status.value||undefined,customer_id:customerId.value})}`);if(current!==version)return;rows.value=result.data;pages.value=result.meta.pager?.total_pages??1;total.value=result.meta.pager?.total_items??0;}catch(cause){if(current===version)error.value=cause instanceof Error?cause.message:t("resellerSubscriptions.operationFailed");}finally{if(current===version)loading.value=false;}}
async function select(row:BilledSubscription):Promise<void>{if(busy.value)return;const current=++selectionVersion;error.value="";try{const fresh=await item<BilledSubscription>(`/v1/reseller/subscriptions/${row.id}`);if(current===selectionVersion)selected.value=fresh;}catch(cause){if(current===selectionVersion)error.value=cause instanceof Error?cause.message:t("resellerSubscriptions.operationFailed");}}
async function loadPlans():Promise<void>{const current=++planVersion;planLoading.value=true;planError.value="";try{const result=await request<Page<ResellerPlan>>(`/v1/reseller/plans?${query({page:planPage.value,q:q.value})}`);if(current!==planVersion)return;plans.value=result.data;planPages.value=result.meta.pager?.total_pages??1;planTotal.value=result.meta.pager?.total_items??0;}catch(cause){if(current===planVersion)planError.value=cause instanceof Error?cause.message:t("resellerSubscriptions.operationFailed");}finally{if(current===planVersion)planLoading.value=false;}}
async function purchase():Promise<void>{if(intentError.value||busy.value||!customer.value||!auth.can("subscriptions","create"))return;if(!intent.value&&(!chosen.value||!payer.value))return;busy.value=true;error.value="";notice.value="";try{if(!intent.value){purchaseKey.value ||= newRequestKey();intent.value={customer_id:customer.value.id,plan_id:chosen.value!.plan_id,payer_mode:payer.value as "reseller_wallet"|"customer_wallet",purchase_key:purchaseKey.value,expected_price_rial:chosen.value!.price_rial,auto_renew:autoRenew.value};remember(intent.value);}const record=await item<BilledSubscription>("/v1/reseller/subscriptions","POST",intent.value);selected.value=record;remember(null);intent.value=null;purchaseKey.value="";notice.value=t("resellerSubscriptions.purchaseRecorded",{amount:toman(record.price_rial)});chosen.value=null;await load();}catch(cause){error.value=cause instanceof Error?cause.message:t("resellerSubscriptions.operationFailed");if(cause instanceof ApiError&&cause.code==="purchase_price_changed"){intent.value=null;remember(null);chosen.value=null;notice.value=t("resellerSubscriptions.priceChanged");void loadPlans();}}finally{busy.value=false;}}
async function toggle():Promise<void>{const row=selected.value;if(!row||busy.value||!auth.can("subscriptions","update"))return;busy.value=true;error.value="";notice.value="";try{selected.value=await item<BilledSubscription>(`/v1/reseller/subscriptions/${row.id}/auto-renew`,"PATCH",{enabled:!row.auto_renew});notice.value=selected.value.auto_renew?t("resellerSubscriptions.renewalEnabled"):t("resellerSubscriptions.renewalPaused");await load();}catch(cause){error.value=cause instanceof Error?cause.message:t("resellerSubscriptions.operationFailed");}finally{busy.value=false;}}
watch(status,()=>{page.value=1;void load();});onMounted(()=>void start());
</script>
<template><div class="page-head"><div><p class="eyebrow">{{t("resellerSubscriptions.eyebrow")}}</p><h1>{{t("resellerSubscriptions.title",{name:customer?.display_name??t("resellerSubscriptions.reseller")})}}</h1><p class="subtitle">{{t("resellerSubscriptions.description")}}</p></div><RouterLink v-if="auth.can('customers')" to="/reseller/customers" class="btn secondary">{{t("resellerSubscriptions.customers")}}</RouterLink><button class="btn secondary" :disabled="loading||busy" @click="load">{{t("resellerSubscriptions.refresh")}}</button></div><p v-if="error" class="message error" role="alert">{{error}}</p><p v-if="notice" class="message" role="status">{{notice}}</p><div class="split"><section class="card"><div class="card-pad"><label class="field"><span>{{t("resellerSubscriptions.filterStatus")}}</span><select :aria-label="t('resellerSubscriptions.filterStatus')" v-model="status"><option value="">{{t("resellerSubscriptions.all")}}</option><option v-for="(label,value) in labels" :key="value" :value="value">{{label}}</option></select></label></div><div class="table-wrap"><table class="data-table"><thead><tr><th>{{t("resellerSubscriptions.subscriptionCustomer")}}</th><th>{{t("resellerSubscriptions.status")}}</th><th>{{t("resellerSubscriptions.expiry")}}</th><th>{{t("resellerSubscriptions.renewal")}}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" tabindex="0" :class="{'selected-row':selected?.id===row.id}" @click="select(row)" @keydown.enter="select(row)"><td>{{faNumber(row.id)}} / {{faNumber(row.customer_id)}}</td><td>{{labels[row.status]??t('resellerSubscriptions.unknown')}}</td><td>{{faDate(row.expires_at)}}</td><td>{{row.auto_renew?t('resellerSubscriptions.automatic'):t('resellerSubscriptions.manual')}}</td></tr></tbody></table><p v-if="loading" class="empty">{{t("resellerSubscriptions.loading")}}</p><p v-else-if="!rows.length&&!error" class="empty">{{t("resellerSubscriptions.empty")}}</p></div><div class="pager"><button :disabled="page<=1||loading||busy" @click="page--;load()">‹</button><span>{{faNumber(page)}} · {{faNumber(total)}} {{t("resellerSubscriptions.subscriptionCount")}}</span><button :disabled="page>=pages||loading||busy" @click="page++;load()">›</button></div></section><div class="stack"><section v-if="selected" class="card card-pad"><h2>{{t("resellerSubscriptions.subscriptionId",{id:faNumber(selected.id)})}}</h2><div class="detail-line"><span>{{t("resellerSubscriptions.customer")}}</span><strong>{{faNumber(selected.customer_id)}}</strong></div><div class="detail-line"><span>{{t("resellerSubscriptions.payingWallet")}}</span><strong>{{selected.reseller_billing?.payer_mode==='reseller_wallet'?t('resellerSubscriptions.reseller'):t('resellerSubscriptions.customer')}} · {{faNumber(selected.payer_customer_id)}}</strong></div><div class="detail-line"><span>{{t("resellerSubscriptions.periodPrice")}}</span><strong>{{toman(selected.price_rial)}}</strong></div><div class="detail-line"><span>{{t("resellerSubscriptions.usageQuota")}}</span><strong>{{faNumber(selected.used_bytes)}} / {{(selected.quota_bytes === null ? t("resellerSubscriptions.unlimited") : faNumber(selected.quota_bytes))}}</strong></div><div class="detail-line"><span>{{t("resellerSubscriptions.renewalCount")}}</span><strong>{{faNumber(selected.renewal_count)}}</strong></div><p v-if="selected.reseller_billing" class="hint-box">{{t("resellerSubscriptions.priceRenewal")}}: {{selected.reseller_billing.renewal_price_mode==='purchase_snapshot'?t('resellerSubscriptions.snapshotPrice'):t('resellerSubscriptions.currentAgreement')}} · {{t("resellerSubscriptions.permissionRenewal")}}: {{selected.reseller_billing.renewal_availability_mode==='purchase_snapshot'?t('resellerSubscriptions.snapshotPermission'):t('resellerSubscriptions.currentAgreementPlan')}}</p><p v-if="selected.failure_reason" class="message error">{{selected.failure_reason}}</p><button v-if="auth.can('subscriptions','update')&&selected.entitlement_kind!=='trial'&&!['failed','cancelled'].includes(selected.status)" class="btn secondary" :disabled="busy" @click="toggle">{{selected.auto_renew?t('resellerSubscriptions.disableRenewal'):t('resellerSubscriptions.enableRenewal')}}</button></section>
<section v-if="customer&&profile&&auth.can('subscriptions','create')" class="card card-pad"><h2>{{t("resellerSubscriptions.purchaseFor",{name:customer.display_name})}}</h2><p v-if="intentError" class="message error" role="alert">{{intentError}}</p><p v-if="intent" class="hint-box">{{t("resellerSubscriptions.retryingSame",{amount:toman(intent.expected_price_rial),wallet:intent.payer_mode==='reseller_wallet'?t('resellerSubscriptions.reseller'):t('resellerSubscriptions.customer')})}}</p><template v-else><p v-if="!profile.sales_enabled" class="hint-box">{{t("resellerSubscriptions.salesPaused")}}</p><p v-if="!auth.can('catalog')" class="hint-box">{{t("resellerSubscriptions.catalogAccessRequired")}}</p><template v-else><p v-if="chosen">{{t("resellerSubscriptions.selectedPlan")}}: {{chosen.title}} · {{toman(chosen.price_rial)}}</p><div class="toolbar"><label class="field"><span>{{t("resellerSubscriptions.findPlan")}}</span><input v-model="q" @keydown.enter.prevent="planPage=1;loadPlans()"/></label><button class="btn secondary" :disabled="busy||planLoading" @click="planPage=1;loadPlans()">{{t("resellerSubscriptions.search")}}</button></div><p v-if="planError" class="message error">{{planError}}</p><p v-if="planLoading">{{t("resellerSubscriptions.loading")}}</p><div class="inline-actions"><button v-for="plan in plans" :key="plan.id" class="btn small secondary" :disabled="busy" :aria-pressed="chosen?.id===plan.id" @click="chosen=plan">{{plan.title}} · {{toman(plan.price_rial)}}</button></div><div class="pager"><button :disabled="planPage<=1||planLoading" @click="planPage--;loadPlans()">‹</button><span>{{faNumber(planPage)}} · {{faNumber(planTotal)}} {{t("resellerSubscriptions.plan")}}</span><button :disabled="planPage>=planPages||planLoading" @click="planPage++;loadPlans()">›</button></div></template><label class="field"><span>{{t("resellerSubscriptions.payingWallet")}}</span><select :aria-label="t('resellerSubscriptions.payingWallet')" v-model="payer" :disabled="busy||profile.policy.payer_mode!=='either'" required><option value="" disabled>{{t("resellerSubscriptions.selectOption")}}</option><option v-if="profile.policy.payer_mode!=='customer_wallet'" value="reseller_wallet">{{t("resellerSubscriptions.reseller")}}</option><option v-if="profile.policy.payer_mode!=='reseller_wallet'" value="customer_wallet">{{t("resellerSubscriptions.customer")}}</option></select></label><label class="check-row"><input v-model="autoRenew" type="checkbox" :disabled="busy"/>{{t("resellerSubscriptions.autoRenew")}}</label></template><button class="btn" :disabled="busy||Boolean(intentError)||(!intent&&(!chosen||!payer||!profile.sales_enabled))" @click="purchase">{{intent?t('resellerSubscriptions.retryPurchase'):t('resellerSubscriptions.purchase')}}</button></section></div></div></template>
